#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_H 100
#define MAX_W 100

int H, W;
char grid[MAX_H][MAX_W];
int strength[MAX_H][MAX_W];
int visited[MAX_H][MAX_W];
int empty_adj[MAX_H][MAX_W];

int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

int in_bounds(int x, int y) {
    return x >= 0 && x < H && y >= 0 && y < W;
}

// BFS to compute empty_adj for all cells
void compute_empty_adj() {
    // Initialize with 0
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            empty_adj[i][j] = 0;

    // For each cell, count adjacent empty squares
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == '.') continue; // empty squares themselves
            int cnt = 0;
            for (int d = 0; d < 4; d++) {
                int ni = i + dx[d];
                int nj = j + dy[d];
                if (in_bounds(ni, nj) && grid[ni][nj] == '.')
                    cnt++;
            }
            empty_adj[i][j] = cnt;
        }
    }
}

// BFS to find all castle squares that will collapse in the current wave
void find_collapsing(int *collapse_list, int *collapse_count) {
    *collapse_count = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] != '.' && empty_adj[i][j] >= strength[i][j]) {
                collapse_list[(*collapse_count)++] = i * W + j;
            }
        }
    }
}

int main() {
    scanf("%d %d", &H, &W);
    for (int i = 0; i < H; i++) {
        scanf("%s", grid[i]);
    }

    // Convert grid and store strengths
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9') {
                strength[i][j] = grid[i][j] - '0';
                grid[i][j] = '#'; // mark as castle (non-empty)
            } else {
                strength[i][j] = 0;
                // grid[i][j] is already '.' for empty
            }
        }
    }

    int waves = 0;
    int collapse_list[MAX_H * MAX_W];
    int collapse_count;

    // Initially compute empty_adj
    compute_empty_adj();

    while (1) {
        find_collapsing(collapse_list, &collapse_count);
        if (collapse_count == 0) break;

        waves++;

        // Collapse all marked squares: turn them into empty
        for (int k = 0; k < collapse_count; k++) {
            int pos = collapse_list[k];
            int x = pos / W;
            int y = pos % W;
            grid[x][y] = '.';
            strength[x][y] = 0;
        }

        // Update empty_adj for neighbors of collapsed squares
        // Only need to update cells that are still castle squares
        for (int k = 0; k < collapse_count; k++) {
            int pos = collapse_list[k];
            int x = pos / W;
            int y = pos % W;
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d];
                int ny = y + dy[d];
                if (in_bounds(nx, ny) && grid[nx][ny] != '.') {
                    // This neighbor lost an empty neighbor? Wait, actually it gained an empty neighbor because (x,y) became empty.
                    // So we need to increase its empty_adj count.
                    empty_adj[nx][ny]++;
                }
            }
        }
    }

    printf("%d\n", waves);
    return 0;
}

