int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    char **A = (char **)malloc(H * sizeof(char *));
    for (int i = 0; i < H; i++) {
        A[i] = (char *)malloc((W + 5) * sizeof(char));
        scanf("%s", A[i]);
    }

    int *deg = (int *)calloc(H * W, sizeof(int));
    int *time = (int *)calloc(H * W, sizeof(int));

    Node *q = (Node *)malloc(H * W * sizeof(Node));
    int head = 0, tail = 0;

    int dy[8] = {-1,-1,-1,0,0,1,1,1};
    int dx[8] = {-1,0,1,-1,1,-1,0,1};

    for (int y = 1; y < H - 1; y++) {
        for (int x = 1; x < W - 1; x++) {
            if (A[y][x] == '.') continue;
            int cnt = 0;
            for (int d = 0; d < 8; d++) {
                int ny = y + dy[d], nx = x + dx[d];
                if (A[ny][nx] == '.') cnt++;
            }
            deg[y * W + x] = cnt;
            if (cnt >= A[y][x] - '0') {
                time[y * W + x] = 1;
                q[tail++] = (Node){y, x};
            }
        }
    }

    int ans = 0;

    while (head < tail) {
        Node cur = q[head++];
        int y = cur.y, x = cur.x;
        int t = time[y * W + x];
        if (t > ans) ans = t;

        for (int d = 0; d < 8; d++) {
            int ny = y + dy[d], nx = x + dx[d];
            if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
            if (A[ny][nx] == '.' || time[ny * W + nx] != 0) continue;

            int id = ny * W + nx;
            deg[id]++;
            if (deg[id] >= A[ny][nx] - '0') {
                time[id] = t + 1;
                q[tail++] = (Node){ny, nx};
            }
        }
    }

    printf("%d\n", ans);

    for (int i = 0; i < H; i++) free(A[i]);
    free(A);
    free(deg);
    free(time);
    free(q);
    return 0;
}

