int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for (int i = 0; i < H; ++i) cin >> S[i];

    vector<vector<int>> need(H, vector<int>(W, -1));
    vector<vector<int>> emptyAdj(H, vector<int>(W, 0));
    queue<pair<int,int>> q;

    const int dx[8] = {-1,-1,-1,0,0,1,1,1};
    const int dy[8] = {-1,0,1,-1,1,-1,0,1};

    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (S[i][j] != '.') {
                need[i][j] = S[i][j] - '0';
            }
        }
    }

    // Initial empty-neighbor counts and first wave collapses
    for (int i = 1; i < H - 1; ++i) {
        for (int j = 1; j < W - 1; ++j) {
            if (need[i][j] == -1) continue;
            int cnt = 0;
            for (int d = 0; d < 8; ++d) {
                int ni = i + dx[d], nj = j + dy[d];
                if (S[ni][nj] == '.') ++cnt;
            }
            emptyAdj[i][j] = cnt;
            if (cnt >= need[i][j]) q.push({i, j});
        }
    }

    int waves = 0;

    while (!q.empty()) {
        int sz = q.size();
        ++waves;

        vector<pair<int,int>> collapsed;
        collapsed.reserve(sz);

        while (sz--) {
            auto [x, y] = q.front();
            q.pop();
            if (S[x][y] == '.') continue; // already collapsed earlier in same wave
            S[x][y] = '.';
            collapsed.push_back({x, y});
        }

        queue<pair<int,int>> nq;
        for (auto [x, y] : collapsed) {
            for (int d = 0; d < 8; ++d) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
                if (S[nx][ny] == '.') continue;
                ++emptyAdj[nx][ny];
                if (emptyAdj[nx][ny] == need[nx][ny]) {
                    nq.push({nx, ny});
                }
            }
        }

        q = move(nq);
    }

    cout << waves << '\n';
    return 0;
}

