public class Main {
    static final int[] dx = {-1, 1, 0, 0};
    static final int[] dy = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int H = Integer.parseInt(st.nextToken());
        int W = Integer.parseInt(st.nextToken());

        int[][] strength = new int[H][W];
        int[][] emptyCount = new int[H][W];
        boolean[][] isCastle = new boolean[H][W];
        Queue<int[]> queue = new ArrayDeque<>();

        for (int i = 0; i < H; i++) {
            String line = br.readLine();
            for (int j = 0; j < W; j++) {
                char c = line.charAt(j);
                if (c == '.') {
                    isCastle[i][j] = false;
                    strength[i][j] = 0;
                    // initially empty squares are "collapsed" at wave 0
                    queue.add(new int[]{i, j, 0});
                } else {
                    isCastle[i][j] = true;
                    strength[i][j] = c - '0';
                }
            }
        }

        // compute initial empty neighbor count for each castle square
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (isCastle[i][j]) {
                    int cnt = 0;
                    for (int d = 0; d < 4; d++) {
                        int ni = i + dx[d];
                        int nj = j + dy[d];
                        if (ni >= 0 && ni < H && nj >= 0 && nj < W) {
                            if (!isCastle[ni][nj]) cnt++;
                        }
                    }
                    emptyCount[i][j] = cnt;
                    // if already meets condition, collapse at wave 1
                    if (cnt >= strength[i][j]) {
                        queue.add(new int[]{i, j, 1});
                        isCastle[i][j] = false; // mark as collapsed
                    }
                }
            }
        }

        int waveCount = 0;
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0], y = cur[1], wave = cur[2];
            // update wave count: the last wave that causes a collapse
            if (wave > waveCount) waveCount = wave;

            // spread effect to neighbors
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d];
                int ny = y + dy[d];
                if (nx >= 0 && nx < H && ny >= 0 && ny < W && isCastle[nx][ny]) {
                    emptyCount[nx][ny]++;
                    if (emptyCount[nx][ny] >= strength[nx][ny]) {
                        // collapse at next wave
                        queue.add(new int[]{nx, ny, wave + 1});
                        isCastle[nx][ny] = false;
                    }
                }
            }
        }

        System.out.println(waveCount);
    }
}

