public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int H = fs.nextInt();
        int W = fs.nextInt();

        char[][] grid = new char[H][W];
        for (int i = 0; i < H; i++) {
            grid[i] = fs.next().toCharArray();
        }

        int[][] emptyCnt = new int[H][W];
        int[][] wave = new int[H][W];
        for (int[] row : wave) Arrays.fill(row, -1);

        ArrayDeque<int[]> q = new ArrayDeque<>();

        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

        // Initial collapses: castle squares already adjacent to enough empty squares.
        for (int r = 1; r < H - 1; r++) {
            for (int c = 1; c < W - 1; c++) {
                if (grid[r][c] == '.') continue;
                int cnt = 0;
                for (int d = 0; d < 8; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (grid[nr][nc] == '.') cnt++;
                }
                emptyCnt[r][c] = cnt;
                int strength = grid[r][c] - '0';
                if (cnt >= strength) {
                    wave[r][c] = 1;
                    q.add(new int[]{r, c});
                }
            }
        }

        int answer = 0;

        // Multi-source BFS by wave number.
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            answer = Math.max(answer, wave[r][c]);

            for (int d = 0; d < 8; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                if (grid[nr][nc] == '.' || wave[nr][nc] != -1) continue;

                emptyCnt[nr][nc]++;
                int strength = grid[nr][nc] - '0';
                if (emptyCnt[nr][nc] >= strength) {
                    wave[nr][nc] = wave[r][c] + 1;
                    q.add(new int[]{nr, nc});
                }
            }
        }

        System.out.println(answer);
    }
}

