import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    H, W = map(int, input().split())
    grid = [list(input().strip()) for _ in range(H)]

    # Convert to integer strength for castle squares, 0 for empty
    strength = [[0]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if grid[i][j] != '.':
                strength[i][j] = int(grid[i][j])

    exposed = [[0]*W for _ in range(H)]
    dq = deque()

    # Initialize with border empty cells
    for i in range(H):
        for j in range(W):
            if i == 0 or i == H-1 or j == 0 or j == W-1:
                if strength[i][j] == 0:
                    dq.append((i, j))
                else:
                    # border castle will be exposed from outside
                    exposed[i][j] += 1

    # Directions
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]

    # Also enqueue any cell that is empty inside but reachable from border
    # Actually we will process as BFS from border empties
    visited = [[False]*W for _ in range(H)]
    for i,j in dq:
        visited[i][j] = True

    wave_count = 0
    while dq:
        # Process one wave
        next_dq = deque()
        collapsed_this_wave = False

        while dq:
            x, y = dq.popleft()
            for dx, dy in dirs:
                nx, ny = x+dx, y+dy
                if 0 <= nx < H and 0 <= ny < W and not visited[nx][ny]:
                    if strength[nx][ny] > 0:
                        exposed[nx][ny] += 1
                        if exposed[nx][ny] >= strength[nx][ny]:
                            visited[nx][ny] = True
                            next_dq.append((nx, ny))
                            collapsed_this_wave = True

        if collapsed_this_wave:
            wave_count += 1
        dq = next_dq

    print(wave_count)

